function host.CreateTab()
    local facade={}
    function facade:AddSection(title,desc)
        local page=title:match("^(TRAIN)") or title:match("^(COMBAT)") or title:match("^(MISC)") or "MISC"
        local tab=getTab(page)
        sides[page]+=1
        local info={Name=title,Desc=desc}
        local group=sides[page]%2==0 and tab:AddRightGroupbox(info) or tab:AddLeftGroupbox(info)
        local sec={}
        function sec:AddButton(name,cb) return group:CreateButton({Name=name,Callback=cb}) end
        function sec:AddToggle(name,cb)
            local ctl=group:CreateToggle({Name=name,Default=false,Callback=cb})
            return function(value) ctl:Set(value) end
        end
        function sec:AddSlider(name,min,max,default,cb)
            local ctl=group:CreateSlider({Name=name,Min=min,Max=max,Default=default,Callback=cb})
            return {SetValue=function(_,v) ctl:Set(v) end,GetValue=function() return ctl:Get() end}
        end
        function sec:AddTextBox(name,cb)
            local ctl=group:CreateInput({Name=name,Callback=cb})
            return {SetValue=function(_,v) ctl:Set(v); if cb then cb(v) end end}
        end
        function sec:AddDropdown(name,options,cb)
            local ctl=group:CreateDropdown({Name=name,Options=options,Default=options[1],Callback=cb})
            return {SetValue=function(_,v) ctl:Set(v) end,ChangeItems=function(_,v) ctl:Refresh(v,true) end,Refresh=function(_,v,pick) ctl:Refresh(v,false);if pick then ctl:Set(pick) end end}
        end
        function sec:AddLabel(text)
            local ctl=group:CreateLabel(text)
            return {SetValue=function(_,v) ctl:Set(v) end}
        end
        return sec
    end
    return facade
end
