"KkhQrb^E!OwsK@Td5/kS:(jXjU`$5rY/PDmuo:K2NU^YR;ybI6VU]|9N60mYo+>8#(GQgh*mQz<i7q!oMhA","|`g?`=r&v8)lt@_(7+myKtCXCZ1ms9@gbVyM^+y.0$Fs-P^2!!OUyK/dyr0aCdR"},{3,4,5,7,1,2,8,6},580,575,181,3701040710,13,17,5,1,59519,3667150037,1}}local _i={}local _X="-Hn9l%QuP8g5O^[)kityZWNKA`m#D@bV+pTU;c/v<x2C7]q?*F!.6Y(:1S3Mr&RsXjh|4aEwz0BGI$d~=oe_>"local _x={}local _b=string.byte local _j=table.concat local _w=math.floor for _I=1,#_X do _x[_b(_X,_I)]=_I-1 end local function _X(_I)local _R=_i[_I];if _R~=nil then return _R end local _R=_E[_I];if _R==nil then error("BG:SG",0)end local _E,_o=_R[1],_R[2]local _s={};for _d=1,#_o do _s[_d]=_E[_o[_d]]end local _E=_j(_s);if#_E%5~=0 then error("BG:S85",0)end local _j=buffer.create(_R[4])
